// friday13.cs — Friday the 13th experiments (proleptic Gregorian calendar)

// Find the earliest Friday the 13th starting from 0001-01-01
var date = new DateOnly(1, 1, 13); // start checking the 13th of each month
DateOnly? earliest = null;

for (int year = 1; year <= 400 && earliest is null; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateOnly(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            earliest = d;
            break;
        }
    }
}

Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd} ({earliest?.DayOfWeek})");

// Count Friday the 13ths in a full 400-year cycle (the Gregorian calendar repeats every 400 years)
int count = 0;
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        if (new DateOnly(year, month, 13).DayOfWeek == DayOfWeek.Friday)
            count++;
    }
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");

// Bonus: which day-of-week lands on the 13th most often?
var dayCounts = new int[7];
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        dayCounts[(int)new DateOnly(year, month, 13).DayOfWeek]++;
    }
}

Console.WriteLine("\n13th-of-month distribution over 400 years:");
foreach (DayOfWeek dow in Enum.GetValues<DayOfWeek>())
{
    var bar = new string('█', dayCounts[(int)dow] / 10);
    Console.WriteLine($"  {dow,-9} {dayCounts[(int)dow],4}  {bar}");
}

